#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <queue>
#include <algorithm>

using namespace std;

// 宏：快速4循环置换
#define CYCLE4(a,b,c,d) {char _t=s[a]; s[a]=s[d]; s[d]=s[c]; s[c]=s[b]; s[b]=_t;}

struct Cube {
    char s[54];
    
    void read() {
        string faces[6];
        for (int i = 0; i < 6; ++i) cin >> faces[i];
        for (int i = 0; i < 9; ++i) {
            s[i]=faces[0][i]; s[9+i]=faces[1][i]; s[18+i]=faces[2][i];
            s[27+i]=faces[3][i]; s[36+i]=faces[4][i]; s[45+i]=faces[5][i];
        }
    }

    bool is_solved() const {
        for (int i = 0; i < 6; ++i) if(s[i*9]!=s[i*9+1]) return false;
        return true;
    }

    // 将 54 字符状态压缩为 64 位无符号整数，用于哈希表
    unsigned long long hash() const {
        unsigned long long h = 0;
        for (int i = 0; i < 54; ++i) {
            h = h * 131 + (s[i] - 'A' + 1); // 字符转数字
        }
        return h;
    }
};

// 顺时针旋转 90 度
inline void apply_move(Cube& c, int m) {
    char* s = c.s;
    switch (m) {
        case 0: CYCLE4(0,2,8,6); CYCLE4(1,5,7,3); CYCLE4(36,27,45,18); CYCLE4(37,28,46,19); CYCLE4(38,29,47,20); break; // U
        case 1: CYCLE4(9,11,17,15); CYCLE4(10,14,16,12); CYCLE4(42,33,51,24); CYCLE4(43,34,52,25); CYCLE4(44,35,53,26); break; // D
        case 2: CYCLE4(18,20,26,24); CYCLE4(19,23,25,21); CYCLE4(0,36,9,53); CYCLE4(3,39,12,50); CYCLE4(6,42,15,47); break; // L
        case 3: CYCLE4(27,29,35,33); CYCLE4(28,32,34,30); CYCLE4(8,45,17,44); CYCLE4(5,48,14,41); CYCLE4(2,51,11,38); break; // R
        case 4: CYCLE4(36,38,44,42); CYCLE4(37,41,43,39); CYCLE4(6,27,47,24); CYCLE4(7,30,46,23); CYCLE4(8,33,45,20); break; // F
        case 5: CYCLE4(45,47,53,51); CYCLE4(46,50,52,48); CYCLE4(2,18,53,35); CYCLE4(1,21,50,32); CYCLE4(0,24,47,29); break; // B
    }
}

// 逆时针旋转 90 度 (顺时针3次)
inline void apply_move_inv(Cube& c, int m) {
    apply_move(c, m); apply_move(c, m); apply_move(c, m);
}

const char MOVE_NAMES[] = {'U', 'D', 'L', 'R', 'F', 'B'};
const int INV_MAP[] = {1, 0, 3, 2, 5, 4}; // U与D互逆, L与R互逆, F与B互逆

// 强剪枝：避免连续操作同一面，或同轴面来回震荡
bool is_bad_move(int last, int curr) {
    if (last == curr) return true;
    // 同轴剪枝：U/D, L/R, F/B 互为 0/1, 2/3, 4/5
    if ((last >> 1) == (curr >> 1) && curr > last) return true; 
    return false;
}

// 双向 BFS 搜索
vector<int> bidirectional_bfs(Cube start) {
    Cube goal;
    char faces_c[6] = {'W', 'Y', 'R', 'O', 'G', 'B'};
    for(int i=0; i<6; ++i) for(int j=0; j<9; ++j) goal.s[i*9+j] = faces_c[i];

    if (start.hash() == goal.hash()) return {};

    unordered_map<unsigned long long, vector<int>> vis_f, vis_b;
    queue<pair<Cube, int>> q_f, q_b;

    vis_f[start.hash()] = {};
    vis_b[goal.hash()] = {};
    q_f.push({start, -1});
    q_b.push({goal, -1});

    int depth_f = 0, depth_b = 0;
    const int MAX_DEPTH = 8; // 单侧最多搜索 8 层 (8+8=16, 覆盖绝大部分情况)

    while (!q_f.empty() || !q_b.empty()) {
        // 正向扩展一层
        if (!q_f.empty()) {
            int sz = q_f.size();
            for (int i = 0; i < sz; ++i) {
                auto [cur, last_move] = q_f.front(); q_f.pop();
                for (int m = 0; m < 6; ++m) {
                    if (last_move != -1 && is_bad_move(last_move, m)) continue;
                    Cube next = cur;
                    apply_move(next, m);
                    unsigned long long h = next.hash();
                    if (vis_f.count(h)) continue;
                    
                    vector<int> path = vis_f[cur.hash()];
                    path.push_back(m);
                    vis_f[h] = path;
                    
                    // 检查是否与反向相遇
                    if (vis_b.count(h)) {
                        vector<int> res_path = vis_f[h];
                        vector<int> back_path = vis_b[h];
                        // 反向路径需要翻转操作顺序并取逆
                        reverse(back_path.begin(), back_path.end());
                        for(int bm : back_path) res_path.push_back(INV_MAP[bm]);
                        return res_path;
                    }
                    if (path.size() < MAX_DEPTH) q_f.push({next, m});
                }
            }
            depth_f++;
        }

        // 反向扩展一层 (逻辑对称)
        if (!q_b.empty()) {
            int sz = q_b.size();
            for (int i = 0; i < sz; ++i) {
                auto [cur, last_move] = q_b.front(); q_b.pop();
                for (int m = 0; m < 6; ++m) {
                    if (last_move != -1 && is_bad_move(last_move, m)) continue;
                    Cube next = cur;
                    apply_move(next, m); // 反向图也用正向动作扩展
                    unsigned long long h = next.hash();
                    if (vis_b.count(h)) continue;
                    
                    vector<int> path = vis_b[cur.hash()];
                    path.push_back(m);
                    vis_b[h] = path;
                    
                    if (vis_f.count(h)) {
                        vector<int> res_path = vis_f[h];
                        vector<int> back_path = vis_b[h];
                        reverse(back_path.begin(), back_path.end());
                        for(int bm : back_path) res_path.push_back(INV_MAP[bm]);
                        return res_path;
                    }
                    if (path.size() < MAX_DEPTH) q_b.push({next, m});
                }
            }
            depth_b++;
        }
    }
    return {}; // 理论上不会发生
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Cube cube;
    cube.read();

    vector<int> path = bidirectional_bfs(cube);
    
    cout << path.size() << " ";
    for (int m : path) cout << MOVE_NAMES[m];
    cout << "\n";

    return 0;
}
